"use client";

import Link from "next/link";
import Image from "next/image";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { jsPDF } from "jspdf";
import { CareCanvas } from "@/components/landing/care-thread";
import { LivingCard } from "@/components/ui/living-card";
import { CtaButton } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { supabase } from "@/lib/supabase/client";

type View = "overview" | "team" | "clients" | "schedule" | "care" | "reports";
type Caregiver = { id: string; name: string; email: string; assigned_client_count: number };
type Client = { id: string; name: string; notes: string };
type Visit = { id: string; client_id: string; caregiver_id: string | null; date: string; start_time: string; end_time: string; status: "scheduled" | "in_progress" | "completed" | "missed" };
type CareItem = { id?: string; client_id: string; item_type: "medication" | "routine"; title: string; dosage: string; instruction: string; scheduled_time: string; weekdays: number[] };
type TaskInstance = { id: string; client_id: string; due_date: string; item_type: "medication" | "routine"; title_snapshot: string; is_skipped: boolean };
type TaskLog = { client_id: string; status: "pending" | "done" | "missed"; task_instance_id: string | null; completed_by: string | null };
type CareNote = { client_id: string; author_id: string; text: string; created_at: string };
type Workspace = { leaderName: string; agencyName: string; caregivers: Caregiver[]; clients: Client[]; visits: Visit[]; assignments: { client_id: string; caregiver_id: string }[]; careItems: CareItem[]; taskInstances: TaskInstance[]; taskLogs: TaskLog[]; notes: CareNote[] };
const NAV: { id: View; label: string }[] = [{ id: "overview", label: "Overview" }, { id: "team", label: "Care team" }, { id: "clients", label: "Clients" }, { id: "schedule", label: "Schedule" }, { id: "care", label: "Care plans" }, { id: "reports", label: "Reports" }];
const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const field = "w-full rounded-2xl border border-white/12 bg-white/[.07] px-4 py-3 text-sm text-white shadow-[inset_0_1px_0_rgba(255,255,255,.06),0_10px_24px_-22px_rgba(0,0,0,.85)] outline-none transition-[border-color,box-shadow,background-color] duration-200 placeholder:text-white/35 hover:border-kelo-300/45 hover:bg-white/[.09] focus:border-kelo-300 focus:bg-white/[.1] focus:ring-4 focus:ring-kelo-500/15 disabled:cursor-not-allowed disabled:opacity-45";
const selectField = `${field} agency-select`;
const fieldLabel = "mb-2 flex items-center gap-2 text-sm font-semibold text-white/78";
const fieldHint = "mt-1.5 text-xs leading-relaxed text-white/42";

export function AgencyDashboard() {
  const router = useRouter(); const [view, setView] = useState<View>("overview"); const [workspace, setWorkspace] = useState<Workspace | null>(null); const [message, setMessage] = useState("Loading your agency workspace…");
  const refresh = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return router.replace("/for-agencies");
    const { data: profile } = await supabase.from("profiles").select("name, role, agency_id").eq("id", user.id).single();
    if (!profile?.agency_id || profile.role !== "team_leader") { await supabase.auth.signOut(); return router.replace("/for-agencies"); }
    const { data: agency } = await supabase.from("agencies").select("name, leader_id").eq("id", profile.agency_id).maybeSingle();
    if (!agency || agency.leader_id !== user.id) { await supabase.auth.signOut(); return router.replace("/for-agencies"); }
    await supabase.rpc("generate_task_instances", { p_start: iso(new Date()), p_end: iso(addDays(new Date(), 45)), p_client_id: null });
    const [team, clients, visits, assignments, careItems, taskInstances, taskLogs, notes] = await Promise.all([supabase.rpc("get_agency_caregivers"), supabase.from("clients").select("id, name, notes").order("created_at"), supabase.from("visits").select("id, client_id, caregiver_id, date, start_time, end_time, status").order("date").order("start_time"), supabase.rpc("get_client_caregiver_assignments"), supabase.from("care_schedules").select("id, client_id, item_type, title_snapshot, dosage_snapshot, instruction_snapshot, scheduled_time, weekdays").eq("active", true).order("scheduled_time"), supabase.from("scheduled_task_instances").select("id, client_id, due_date, item_type, title_snapshot, is_skipped").order("due_date"), supabase.from("task_logs").select("client_id, status, task_instance_id, completed_by"), supabase.from("handoff_notes").select("client_id, author_id, text, created_at").order("created_at", { ascending: false })]);
    if (team.error || clients.error || visits.error || assignments.error || careItems.error) return setMessage("We couldn't load the agency data. Please refresh and try again.");
    const plan = (careItems.data || []).map((item) => ({ id: item.id, client_id: item.client_id, item_type: item.item_type as CareItem["item_type"], title: item.title_snapshot, dosage: item.dosage_snapshot || "", instruction: item.instruction_snapshot || "", scheduled_time: item.scheduled_time, weekdays: item.weekdays || [] })) as CareItem[];
    setWorkspace({ leaderName: profile.name || user.email?.split("@")[0] || "there", agencyName: agency.name, caregivers: (team.data || []) as Caregiver[], clients: (clients.data || []) as Client[], visits: (visits.data || []) as Visit[], assignments: (assignments.data || []) as { client_id: string; caregiver_id: string }[], careItems: plan, taskInstances: (taskInstances.data || []) as TaskInstance[], taskLogs: (taskLogs.data || []) as TaskLog[], notes: (notes.data || []) as CareNote[] }); setMessage("");
  };
  useEffect(() => {
    void refresh();
    const interval = window.setInterval(() => {
      const active = document.activeElement;
      const editing = active instanceof HTMLSelectElement || active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement;
      if (document.visibilityState === "visible" && !editing) void refresh();
    }, 10_000);
    return () => window.clearInterval(interval);
  }, []);
  const heading = NAV.find((x) => x.id === view)?.label || "Overview";
  return <CareCanvas variant="agency"><section className="relative min-h-screen px-4 pb-10 pt-24 sm:px-6 sm:pt-28"><div className="mx-auto max-w-7xl overflow-hidden rounded-[2rem] border border-white/12 bg-[#090d24]/65 shadow-[0_30px_90px_-45px_rgba(0,0,0,.95)] backdrop-blur-xl"><div className="flex min-h-[720px]"><aside className="hidden w-60 shrink-0 border-r border-white/10 bg-white/[.035] p-5 lg:block"><Link href="/for-agencies" className="flex items-center gap-3 rounded-2xl px-3 py-3 text-white"><span className="relative h-9 w-9 shrink-0 overflow-hidden rounded-xl border border-white/15 bg-white shadow-[0_8px_18px_-10px_rgba(0,0,0,.7)]"><Image src="/kelo-care-logo.jpg" alt="Kelo Care" fill sizes="36px" className="object-cover" priority /></span><span className="font-semibold">Kelo Care</span></Link><p className="mt-8 px-3 text-[10px] font-bold uppercase tracking-[.2em] text-white/30">Agency workspace</p><nav className="mt-3 space-y-1">{NAV.map((x) => <button key={x.id} onClick={() => setView(x.id)} className={cn("w-full rounded-2xl px-3 py-3 text-left text-sm font-medium", view === x.id ? "bg-kelo-500/16 text-white ring-1 ring-kelo-300/18" : "text-white/52 hover:bg-white/[.055] hover:text-white")}>{x.label}</button>)}</nav></aside><div className="min-w-0 flex-1 p-5 sm:p-7 lg:p-9"><header className="flex flex-wrap items-center justify-between gap-4 border-b border-white/10 pb-6"><div><p className="text-xs font-semibold uppercase tracking-[.24em] text-kelo-200">{heading}</p><h1 className="mt-2 text-3xl font-medium tracking-[-.045em] text-white">{view === "overview" ? `Welcome back, ${workspace?.leaderName || "…"}.` : heading}</h1></div><button onClick={() => { void supabase.auth.signOut().then(() => router.replace("/for-agencies")); }} className="rounded-full border border-white/12 px-3 py-2 text-sm text-white/65 hover:bg-white/[.06]">Sign out</button></header><div className="mt-5 flex gap-2 overflow-x-auto lg:hidden">{NAV.map((x) => <button key={x.id} onClick={() => setView(x.id)} className={cn("whitespace-nowrap rounded-full px-3 py-2 text-sm", view === x.id ? "bg-kelo-500 text-white" : "bg-white/[.06] text-white/55")}>{x.label}</button>)}</div>{message && <p role="status" className="mt-5 rounded-2xl border border-kelo-300/25 bg-kelo-500/12 px-4 py-3 text-sm text-kelo-100">{message}</p>}{workspace && <main className="mt-7"><Screen view={view} workspace={workspace} refresh={refresh} /></main>}</div></div></div></section></CareCanvas>;
}

function Screen({ view, workspace, refresh }: { view: View; workspace: Workspace; refresh: () => Promise<void> }) { if (view === "team") return <Team workspace={workspace} refresh={refresh} />; if (view === "clients") return <Clients workspace={workspace} refresh={refresh} />; if (view === "schedule") return <Schedule workspace={workspace} refresh={refresh} />; if (view === "care") return <CarePlans workspace={workspace} refresh={refresh} />; if (view === "reports") return <Reports workspace={workspace} />; const today = workspace.visits.filter((v) => v.date === iso(new Date())); return <><div className="grid gap-4 sm:grid-cols-3">{[[workspace.caregivers.length, "Active caregivers"], [today.length, "Visits today"], [today.filter((v) => !v.caregiver_id).length, "Needs coverage"]].map(([n, l]) => <LivingCard key={String(l)} className="p-5"><p className="text-4xl font-medium text-white">{n}</p><p className="mt-3 font-semibold text-white">{l}</p></LivingCard>)}</div><div className="mt-5"><Appointments workspace={workspace} /></div></>; }
function Team({ workspace, refresh }: { workspace: Workspace; refresh: () => Promise<void> }) { const [email, setEmail] = useState(""); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const invite = async (e: FormEvent) => { e.preventDefault(); setBusy(true); const { error } = await supabase.rpc("create_caregiver_invite", { invitee_email: email.trim() }); setNotice(error ? error.message : "Invitation created. The caregiver can accept it securely in Kelo."); if (!error) { setEmail(""); await refresh(); } setBusy(false); }; return <LivingCard className="overflow-hidden p-0"><div className="flex flex-wrap gap-5 p-5"><div className="min-w-[220px] flex-1"><h2 className="font-semibold text-white">Caregiver roster</h2><p className="mt-1 text-sm text-white/45">Invite caregivers to their own Kelo account, then assign clients and visits.</p></div><form onSubmit={invite} className="flex flex-1 flex-wrap gap-2 sm:justify-end"><input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="caregiver@email.com" className={field + " min-w-[210px]"} /><CtaButton type="submit" size="md" disabled={busy}>{busy ? "Sending…" : "Invite caregiver"}</CtaButton></form>{notice && <p className="w-full text-sm text-kelo-100">{notice}</p>}</div><div className="divide-y divide-white/[.07]">{workspace.caregivers.length ? workspace.caregivers.map((c) => <div key={c.id} className="flex flex-wrap justify-between gap-2 p-5"><div><p className="font-semibold text-white">{c.name || "Unnamed caregiver"}</p><p className="text-sm text-white/48">{c.email}</p></div><p className="text-sm text-kelo-100">{c.assigned_client_count} assigned clients</p></div>) : <p className="p-5 text-sm text-white/50">No caregivers have joined this agency yet.</p>}</div></LivingCard>; }
function Clients({ workspace, refresh }: { workspace: Workspace; refresh: () => Promise<void> }) { const [name, setName] = useState(""); const [notes, setNotes] = useState(""); const [caregiver, setCaregiver] = useState(""); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const add = async (e: FormEvent) => { e.preventDefault(); setBusy(true); const { data, error } = await supabase.rpc("create_client", { client_name: name.trim(), client_notes: notes.trim(), client_scope: "agency" }); let detail = error?.message || "Client created and ready for scheduling."; if (!error && caregiver && data?.id) { const assignment = await supabase.from("caregiver_clients").insert({ client_id: data.id, caregiver_id: caregiver }); if (assignment.error) detail = `Client created, but assignment needs attention: ${assignment.error.message}`; } setNotice(detail); if (!error) { setName(""); setNotes(""); setCaregiver(""); await refresh(); } setBusy(false); }; return <div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><LivingCard className="p-6"><h2 className="text-xl font-semibold text-white">Add a client</h2><p className="mt-2 text-sm text-white/48">Save care details and choose a primary caregiver when ready.</p><form onSubmit={add} className="mt-6 space-y-3"><input required value={name} onChange={(e) => setName(e.target.value)} placeholder="Client full name" className={field} /><textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Care notes, preferences, or relevant details" className={field + " min-h-28 resize-y"} /><select value={caregiver} onChange={(e) => setCaregiver(e.target.value)} className={selectField}><option value="">Assign a caregiver later</option>{workspace.caregivers.map((c) => <option key={c.id} value={c.id}>{c.name || c.email}</option>)}</select><CtaButton type="submit" size="md" disabled={busy}>{busy ? "Adding…" : "Add client"}</CtaButton></form>{notice && <p className="mt-4 text-sm text-kelo-100">{notice}</p>}</LivingCard><LivingCard className="overflow-hidden p-0"><div className="p-5"><h2 className="font-semibold text-white">Clients</h2><p className="mt-1 text-sm text-white/45">Shared live with the Kelo app.</p></div><div className="divide-y divide-white/[.07]">{workspace.clients.length ? workspace.clients.map((c) => <div key={c.id} className="p-5"><p className="font-semibold text-white">{c.name}</p><p className="mt-1 text-sm text-white/48">{c.notes || "No care notes added yet."}</p><p className="mt-3 text-xs text-kelo-100">Caregiver: {assigned(c.id, workspace).join(", ") || "Unassigned"}</p></div>) : <p className="p-5 text-sm text-white/50">No agency clients yet.</p>}</div></LivingCard></div>; }
function Schedule({ workspace, refresh }: { workspace: Workspace; refresh: () => Promise<void> }) {
  const monday = mondayOf(new Date());
  const dates = useMemo(() => DAYS.map((_, i) => iso(addDays(monday, i))), [monday]);
  const [client, setClient] = useState(workspace.clients[0]?.id || "");
  const [caregiver, setCaregiver] = useState("");
  const [picked, setPicked] = useState([0]);
  const [start, setStart] = useState("09:00");
  const [end, setEnd] = useState("10:00");
  const [notice, setNotice] = useState("");
  const [busy, setBusy] = useState(false);
  const create = async (event: FormEvent) => { event.preventDefault(); setBusy(true); const { error } = await supabase.rpc("create_visits", { target_client_id: client, visit_dates: picked.map((day) => dates[day]), visit_start_time: start, visit_end_time: end, assigned_caregiver_id: caregiver || null }); setNotice(error ? error.message : `${picked.length} visit${picked.length === 1 ? "" : "s"} scheduled for this week.`); if (!error) await refresh(); setBusy(false); };
  const copy = async () => { const source = workspace.visits.filter((visit) => visit.date >= dates[0] && visit.date <= dates[6]); if (!source.length) return setNotice("There are no visits to copy from this week."); setBusy(true); const results = await Promise.all(source.map((visit) => supabase.rpc("create_visits", { target_client_id: visit.client_id, visit_dates: [iso(addDays(new Date(`${visit.date}T12:00:00`), 7))], visit_start_time: visit.start_time, visit_end_time: visit.end_time, assigned_caregiver_id: visit.caregiver_id }))); const failed = results.find((result) => result.error); setNotice(failed?.error?.message || `${source.length} visits copied to next week.`); if (!failed) await refresh(); setBusy(false); };
  return <div className="grid gap-5 xl:grid-cols-[.95fr_1.05fr]">
    <LivingCard className="p-6 sm:p-7">
      <div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.18em] text-kelo-200">Plan the week</p><h2 className="mt-2 text-xl font-semibold text-white">Weekly schedule</h2><p className="mt-2 text-sm text-white/48">Set appointments for the week of {monday.toLocaleDateString(undefined, { month: "short", day: "numeric" })}.</p></div><button type="button" onClick={copy} disabled={busy} className="rounded-full border border-white/15 bg-white/[.035] px-4 py-2.5 text-xs font-semibold text-white/80 transition hover:border-kelo-300/50 hover:bg-kelo-500/10 disabled:cursor-not-allowed disabled:opacity-40">Copy this week <span aria-hidden="true">→</span></button></div>
      <form onSubmit={create} className="mt-7 space-y-5">
        <div><label htmlFor="schedule-client" className={fieldLabel}>Client</label><select id="schedule-client" required value={client} onChange={(event) => setClient(event.target.value)} className={selectField}><option value="">Choose the client for this visit</option>{workspace.clients.map((entry) => <option key={entry.id} value={entry.id}>{entry.name}</option>)}</select><p className={fieldHint}>The visit and its completed record will be saved to this client.</p></div>
        <div><label htmlFor="schedule-caregiver" className={fieldLabel}>Caregiver <span className="font-normal text-white/38">Optional</span></label><select id="schedule-caregiver" value={caregiver} onChange={(event) => setCaregiver(event.target.value)} className={selectField}><option value="">Leave unassigned for now</option>{workspace.caregivers.map((entry) => <option key={entry.id} value={entry.id}>{entry.name || entry.email}</option>)}</select><p className={fieldHint}>You can leave coverage open and assign it later.</p></div>
        <div className="grid gap-4 sm:grid-cols-2"><div><label htmlFor="schedule-start" className={fieldLabel}>Starts</label><input id="schedule-start" required type="time" value={start} onChange={(event) => setStart(event.target.value)} className={field + " agency-time"} /></div><div><label htmlFor="schedule-end" className={fieldLabel}>Ends</label><input id="schedule-end" required type="time" value={end} onChange={(event) => setEnd(event.target.value)} className={field + " agency-time"} /></div></div>
        <div><p className={fieldLabel}>Visit days</p><div className="grid grid-cols-7 gap-1.5">{DAYS.map((day, index) => <button key={day} type="button" aria-pressed={picked.includes(index)} onClick={() => setPicked((current) => current.includes(index) ? current.filter((value) => value !== index) : [...current, index])} className={cn("rounded-2xl border px-1 py-3 text-xs font-semibold transition", picked.includes(index) ? "border-kelo-300/50 bg-kelo-500 text-white shadow-[0_10px_20px_-14px_rgba(69,118,255,.9)]" : "border-transparent bg-white/[.045] text-white/52 hover:border-white/12 hover:bg-white/[.08]")}>{day}<span className="mt-1 block text-[10px] opacity-70">{new Date(`${dates[index]}T12:00:00`).getDate()}</span></button>)}</div><p className={fieldHint}>Choose every day this visit should repeat during this week.</p></div>
        <CtaButton type="submit" size="md" disabled={busy || !client || !picked.length}>{busy ? "Saving…" : "Schedule visits"}</CtaButton>
      </form>{notice && <p role="status" className="mt-5 rounded-2xl border border-kelo-300/20 bg-kelo-500/10 px-4 py-3 text-sm text-kelo-100">{notice}</p>}
    </LivingCard>
    <Appointments workspace={workspace} weekStart={dates[0]} weekEnd={dates[6]} />
  </div>;
}
function CarePlans({ workspace, refresh }: { workspace: Workspace; refresh: () => Promise<void> }) {
  const [clientId, setClientId] = useState(workspace.clients[0]?.id || ""); const [items, setItems] = useState<CareItem[]>([]); const [kind, setKind] = useState<CareItem["item_type"]>("medication"); const [title, setTitle] = useState(""); const [dosage, setDosage] = useState(""); const [instruction, setInstruction] = useState(""); const [time, setTime] = useState("09:00"); const [days, setDays] = useState([1, 2, 3, 4, 5]); const [fromDay, setFromDay] = useState(1); const [toDay, setToDay] = useState(2); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false);
  useEffect(() => { setItems(workspace.careItems.filter((item) => item.client_id === clientId)); }, [clientId, workspace.careItems]);
  const add = () => { if (!title.trim() || !days.length) return; setItems((current) => [...current, { client_id: clientId, item_type: kind, title: title.trim(), dosage: kind === "medication" ? dosage.trim() : "", instruction: instruction.trim(), scheduled_time: time, weekdays: days }]); setTitle(""); setDosage(""); setInstruction(""); };
  const copyDay = () => { const source = items.filter((item) => item.weekdays.includes(fromDay)); if (!source.length) return setNotice("There are no tasks on that source day yet."); setItems((current) => current.map((item) => item.weekdays.includes(fromDay) && !item.weekdays.includes(toDay) ? { ...item, weekdays: [...item.weekdays, toDay].sort() } : item)); setNotice("That day is now copied into the weekly automation."); };
  const publish = async () => { if (!clientId) return; setBusy(true); const payload = items.map(({ item_type, title: itemTitle, dosage: itemDosage, instruction: itemInstruction, scheduled_time, weekdays }) => ({ item_type, title: itemTitle, dosage: itemDosage, instruction: itemInstruction, scheduled_time, weekdays })); const { data, error } = await supabase.rpc("publish_weekly_care_plan", { p_client_id: clientId, p_items: payload, p_effective_from: iso(new Date()) }); setNotice(error ? error.message : `${data || payload.length} care tasks are now automated every week and synced to Kelo.`); if (!error) await refresh(); setBusy(false); };
  return <div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]">
    <LivingCard className="p-6 sm:p-7"><p className="text-xs font-semibold uppercase tracking-[.2em] text-kelo-200">Automation first</p><h2 className="mt-2 text-xl font-semibold text-white">Weekly care plan</h2><p className="mt-2 text-sm leading-relaxed text-white/48">Build the weekly pattern once. Kelo creates the daily medication and routine tasks automatically.</p>
      <div className="mt-7 space-y-5"><div><label htmlFor="plan-client" className={fieldLabel}>Client</label><select id="plan-client" value={clientId} onChange={(event) => setClientId(event.target.value)} className={selectField}><option value="">Choose the client this plan is for</option>{workspace.clients.map((entry) => <option key={entry.id} value={entry.id}>{entry.name}</option>)}</select><p className={fieldHint}>Choose the person whose daily plan you are building.</p></div><div className="grid gap-4 sm:grid-cols-2"><div><label htmlFor="plan-kind" className={fieldLabel}>Care item</label><select id="plan-kind" value={kind} onChange={(event) => setKind(event.target.value as CareItem["item_type"])} className={selectField}><option value="medication">Medication</option><option value="routine">Routine</option></select></div><div><label htmlFor="plan-time" className={fieldLabel}>Scheduled time</label><input id="plan-time" type="time" value={time} onChange={(event) => setTime(event.target.value)} className={field + " agency-time"} /></div></div><div><label htmlFor="plan-title" className={fieldLabel}>{kind === "medication" ? "Medication name" : "Routine name"}</label><input id="plan-title" value={title} onChange={(event) => setTitle(event.target.value)} placeholder={kind === "medication" ? "e.g. Lisinopril" : "e.g. Morning walk"} className={field} /><p className={fieldHint}>Use the name caregivers should see in their daily checklist.</p></div><div><label htmlFor="plan-dosage" className={fieldLabel}>Dose or amount <span className="font-normal text-white/38">Medication only</span></label><input id="plan-dosage" value={dosage} onChange={(event) => setDosage(event.target.value)} placeholder="e.g. 10 mg or 2 tablets" disabled={kind !== "medication"} className={field} /></div><div><label htmlFor="plan-instructions" className={fieldLabel}>Caregiver instructions <span className="font-normal text-white/38">Optional</span></label><input id="plan-instructions" value={instruction} onChange={(event) => setInstruction(event.target.value)} placeholder="e.g. Take with breakfast, record any concerns" className={field} /></div><div><p className={fieldLabel}>Repeats on</p><div className="grid grid-cols-7 gap-1.5">{DAYS.map((day, index) => { const value = index === 6 ? 0 : index + 1; return <button key={day} type="button" aria-pressed={days.includes(value)} onClick={() => setDays((current) => current.includes(value) ? current.filter((entry) => entry !== value) : [...current, value])} className={cn("rounded-2xl px-1 py-3 text-xs font-semibold transition", days.includes(value) ? "bg-kelo-500 text-white shadow-[0_10px_20px_-14px_rgba(69,118,255,.9)]" : "bg-white/[.05] text-white/50 hover:bg-white/[.09]")}>{day}</button>; })}</div><p className={fieldHint}>Select the days when this care item should appear.</p></div><button type="button" onClick={add} disabled={!clientId || !title.trim() || !days.length} className="rounded-full border border-kelo-300/35 bg-kelo-500/10 px-4 py-2.5 text-sm font-semibold text-kelo-100 transition hover:bg-kelo-500/20 disabled:cursor-not-allowed disabled:opacity-40">Add to plan</button></div>
      <div className="mt-8 border-t border-white/10 pt-6"><p className="text-xs font-semibold uppercase tracking-[.16em] text-white/42">Copy a day forward</p><p className="mt-2 text-sm text-white/48">Reuse an existing day’s routine without re-entering each task.</p><div className="mt-4 grid grid-cols-[1fr_auto_1fr] items-center gap-2"><select aria-label="Copy tasks from day" value={fromDay} onChange={(event) => setFromDay(Number(event.target.value))} className={selectField}>{DAYS.map((day, index) => <option key={day} value={index === 6 ? 0 : index + 1}>{day}</option>)}</select><span className="text-white/45">→</span><select aria-label="Copy tasks to day" value={toDay} onChange={(event) => setToDay(Number(event.target.value))} className={selectField}>{DAYS.map((day, index) => <option key={day} value={index === 6 ? 0 : index + 1}>{day}</option>)}</select></div><button type="button" onClick={copyDay} className="mt-4 text-sm font-semibold text-kelo-100 underline decoration-kelo-300/50 underline-offset-4">Copy day into plan</button></div>
      <CtaButton type="button" onClick={publish} size="md" fullWidth disabled={busy || !clientId} className="mt-8">{busy ? "Publishing…" : "Publish automated care plan"}</CtaButton>{notice && <p role="status" className="mt-4 rounded-2xl border border-kelo-300/20 bg-kelo-500/10 px-4 py-3 text-sm text-kelo-100">{notice}</p>}
    </LivingCard>
    <LivingCard className="overflow-hidden p-0"><div className="flex items-center justify-between gap-3 p-6"><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-kelo-200">Ready to publish</p><h2 className="mt-2 font-semibold text-white">Plan preview</h2><p className="mt-1 text-sm text-white/45">Repeats automatically every week. Completed history is preserved.</p></div><span className="rounded-full bg-kelo-500/15 px-3 py-1 text-xs font-semibold text-kelo-100">{items.length} tasks</span></div><div className="divide-y divide-white/[.07]">{items.length ? items.map((item, index) => <div key={`${item.id || item.title}-${index}`} className="flex items-start justify-between gap-4 p-5"><div><p className="font-semibold text-white">{item.title}</p><p className="mt-1 text-sm text-white/48">{item.item_type === "medication" && item.dosage ? `${item.dosage} · ` : ""}{item.scheduled_time} · {item.weekdays.map(dayName).join(", ")}</p>{item.instruction && <p className="mt-2 text-xs text-kelo-100">{item.instruction}</p>}</div><button type="button" onClick={() => setItems((current) => current.filter((_, itemIndex) => itemIndex !== index))} className="rounded-full border border-white/12 px-3 py-1.5 text-xs text-white/55 transition hover:border-red-300/40 hover:text-red-200">Remove</button></div>) : <p className="p-6 text-sm text-white/50">Choose a client and add medications or routines to build this week’s automated plan.</p>}</div></LivingCard>
  </div>;
}
function Reports({ workspace }: { workspace: Workspace }) {
  const currentMonday = mondayOf(new Date());
  const [clientId, setClientId] = useState(workspace.clients[0]?.id || "");
  const [weekStart, setWeekStart] = useState(iso(currentMonday));
  const start = new Date(`${weekStart}T12:00:00`);
  const end = addDays(start, 6);
  const previousStart = addDays(start, -7);
  const nextStart = addDays(start, 7);
  const inWeek = (date: string, from = start) => date >= iso(from) && date <= iso(addDays(from, 6));
  const clientVisits = workspace.visits.filter((visit) => visit.client_id === clientId && inWeek(visit.date));
  const completedVisits = clientVisits.filter((visit) => visit.status === "completed");
  const priorVisits = workspace.visits.filter((visit) => visit.client_id === clientId && inWeek(visit.date, previousStart));
  const nextVisits = workspace.visits.filter((visit) => visit.client_id === clientId && inWeek(visit.date, nextStart));
  const hours = clientVisits.reduce((total, visit) => total + visitHours(visit), 0);
  const caregiverCounts = clientVisits.reduce<Record<string, number>>((counts, visit) => {
    const name = caregiver(visit.caregiver_id, workspace);
    counts[name] = (counts[name] || 0) + 1;
    return counts;
  }, {});
  const tasks = workspace.taskInstances.filter((task) => task.client_id === clientId && inWeek(task.due_date) && !task.is_skipped);
  const logs = new Map(workspace.taskLogs.filter((log) => log.client_id === clientId && log.task_instance_id).map((log) => [log.task_instance_id!, log]));
  const taskSummary = (filter: (task: TaskInstance) => boolean) => {
    const matching = tasks.filter(filter);
    const done = matching.filter((task) => logs.get(task.id)?.status === "done").length;
    const missed = matching.filter((task) => logs.get(task.id)?.status === "missed").length;
    return { total: matching.length, done, missed };
  };
  const medications = taskSummary((task) => task.item_type === "medication");
  const meals = taskSummary((task) => task.item_type === "routine" && /(meal|breakfast|lunch|dinner)/i.test(task.title_snapshot));
  const activity = taskSummary((task) => task.item_type === "routine" && /(walk|activity|exercise|outside)/i.test(task.title_snapshot));
  const notes = workspace.notes.filter((note) => note.client_id === clientId && inWeek(iso(new Date(note.created_at)))).slice(0, 4);
  const exception = medications.missed ? `${medications.missed} medication dose${medications.missed === 1 ? " was" : "s were"} marked missed this week.` : meals.missed ? `${meals.missed} meal routine${meals.missed === 1 ? " was" : "s were"} marked missed this week.` : "No medication or routine exceptions were recorded this week.";
  const visitComparison = clientVisits.length === priorVisits.length ? `same visits (${clientVisits.length})` : `${clientVisits.length} visits vs ${priorVisits.length}`;
  const dateRange = `${start.toLocaleDateString(undefined, { month: "short", day: "numeric" })}–${end.toLocaleDateString(undefined, { day: "numeric" })}`;
  const nextWeek = nextVisits.length ? `${nextVisits.length} visit${nextVisits.length === 1 ? "" : "s"}, ${Array.from(new Set(nextVisits.map((visit) => new Date(`${visit.date}T12:00:00`).toLocaleDateString(undefined, { weekday: "short" })))).join("–")}, ${Array.from(new Set(nextVisits.map((visit) => visit.start_time))).join(", ")}, ${Array.from(new Set(nextVisits.map((visit) => caregiver(visit.caregiver_id, workspace)))).join(", ")}` : "No visits scheduled yet.";
  const complete = workspace.visits.filter((visit) => visit.status === "completed" && visit.client_id === clientId);
  const summaryLine = `${clientVisits.length} visit${clientVisits.length === 1 ? "" : "s"} · ${formatHours(hours)} · ${Object.entries(caregiverCounts).map(([name, count]) => `${name} (${count})`).join(", ") || "No caregiver assigned"}`;
  const medicationText = medications.total ? `${medications.done} of ${medications.total} doses given${medications.missed ? ` (${medications.missed} missed)` : ""}` : "No medication doses scheduled";
  const mealText = meals.total ? `${meals.done} of ${meals.total} meal routine tasks completed${meals.missed ? ` (${meals.missed} missed)` : ""}` : "No meal routine activity recorded";
  const activityText = activity.total ? `${activity.done} of ${activity.total} activity routine tasks completed${activity.missed ? ` (${activity.missed} missed)` : ""}` : "No activity routine recorded";
  return <div className="space-y-5">
    <LivingCard className="overflow-hidden p-0">
      <div className="border-b border-white/[.08] p-6">
        <p className="text-xs font-semibold uppercase tracking-[.2em] text-kelo-200">Weekly care report</p>
        <div className="mt-4 flex flex-wrap items-end justify-between gap-4">
          <div>
            <h2 className="text-2xl font-medium text-white">{client(clientId, workspace)} <span className="text-white/45">— week of {dateRange}</span></h2>
            <p className="mt-2 text-sm text-white/55">A clear weekly snapshot from the care your team recorded in Kelo.</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button type="button" disabled={!clientId} onClick={() => weeklyPdf({ agencyName: workspace.agencyName, clientName: client(clientId, workspace), dateRange, summaryLine, exception, visits: `${completedVisits.length} of ${clientVisits.length} completed`, medications: medicationText, meals: mealText, activity: activityText, comparison: visitComparison, nextWeek, notes: notes.map((note) => ({ text: note.text, byline: `From ${caregiver(note.author_id, workspace)}, ${new Date(note.created_at).toLocaleDateString(undefined, { weekday: "short" })}` })) })} className="rounded-full bg-kelo-500 px-3 py-2 text-xs font-semibold text-white shadow-[0_8px_20px_-10px_rgba(72,124,255,.8)] transition hover:bg-kelo-400 disabled:cursor-not-allowed disabled:opacity-40">Download weekly PDF</button>
            <button type="button" onClick={() => setWeekStart(iso(previousStart))} className="rounded-full border border-white/15 px-3 py-2 text-xs font-semibold text-white/80 hover:border-kelo-300/50">Previous</button>
            <button type="button" onClick={() => setWeekStart(iso(currentMonday))} className="rounded-full border border-white/15 px-3 py-2 text-xs font-semibold text-white/80 hover:border-kelo-300/50">This week</button>
            <button type="button" onClick={() => setWeekStart(iso(nextStart))} className="rounded-full border border-white/15 px-3 py-2 text-xs font-semibold text-white/80 hover:border-kelo-300/50">Next</button>
          </div>
        </div>
        <select aria-label="Choose client for weekly report" value={clientId} onChange={(event) => setClientId(event.target.value)} className={selectField + " mt-5 max-w-md"}><option value="">Choose client</option>{workspace.clients.map((entry) => <option key={entry.id} value={entry.id}>{entry.name}</option>)}</select>
      </div>
      {clientId ? <div className="p-6">
        <p className="font-semibold text-white">{summaryLine}</p>
        <div className="mt-5 rounded-2xl border border-kelo-300/25 bg-kelo-500/12 p-4"><p className="text-sm leading-relaxed text-kelo-50"><span className="font-semibold text-white">One thing to know:</span> {exception}</p></div>
        <div className="mt-6 grid gap-3 sm:grid-cols-2"><ReportFact title="Visits" value={`${completedVisits.length} of ${clientVisits.length} completed`} /><ReportFact title="Medications" value={medicationText} /><ReportFact title="Meals" value={mealText} /><ReportFact title="Activity" value={activityText} /></div>
        <div className="mt-6 border-t border-white/[.08] pt-5"><p className="text-sm leading-relaxed text-white/70"><span className="font-semibold text-white">Compared with last week:</span> {visitComparison}.</p><p className="mt-4 text-sm leading-relaxed text-white/70"><span className="font-semibold text-white">Next week:</span> {nextWeek}</p></div>
      </div> : <p className="p-6 text-sm text-white/55">Add a client to begin viewing weekly reports.</p>}
    </LivingCard>
    <LivingCard className="overflow-hidden p-0"><div className="p-6"><p className="text-xs font-semibold uppercase tracking-[.2em] text-kelo-200">From the care team</p><h3 className="mt-2 text-xl font-semibold text-white">Caregiver notes</h3></div><div className="divide-y divide-white/[.07]">{notes.length ? notes.map((note) => <div key={`${note.created_at}-${note.author_id}`} className="p-5"><p className="text-sm leading-relaxed text-white/75">“{note.text}”</p><p className="mt-3 text-xs font-semibold text-kelo-100">From {caregiver(note.author_id, workspace)}, {new Date(note.created_at).toLocaleDateString(undefined, { weekday: "short" })}</p></div>) : <p className="p-6 text-sm text-white/50">No caregiver notes were recorded for this client during this week.</p>}</div></LivingCard>
    <LivingCard className="overflow-hidden p-0"><div className="p-6"><p className="text-xs font-semibold uppercase tracking-[.2em] text-kelo-200">Completed care</p><h3 className="mt-2 text-xl font-semibold text-white">Session records</h3><p className="mt-2 text-sm text-white/48">Download a PDF for any individual completed caregiving session.</p></div><div className="divide-y divide-white/[.07]">{complete.length ? complete.map((visit) => <div key={visit.id} className="flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="font-semibold text-white">{visit.date} · {visit.start_time}–{visit.end_time}</p><p className="mt-1 text-sm text-white/48">{caregiver(visit.caregiver_id, workspace)}</p></div><button type="button" onClick={() => pdf(visit, workspace)} className="rounded-full bg-kelo-500 px-4 py-2 text-sm font-semibold text-white">Download session PDF</button></div>) : <p className="p-6 text-sm text-white/50">Completed sessions will appear here once caregivers finish them in Kelo.</p>}</div></LivingCard>
  </div>;
}
function ReportFact({ title, value }: { title: string; value: string }) { return <div className="rounded-2xl bg-white/[.055] p-4"><p className="text-xs font-semibold uppercase tracking-[.15em] text-white/42">{title}</p><p className="mt-2 text-sm leading-relaxed text-white/78">{value}</p></div>; }
function Appointments({ workspace, weekStart, weekEnd }: { workspace: Workspace; weekStart?: string; weekEnd?: string }) {
  const [dateFilter, setDateFilter] = useState<"all" | "today" | "upcoming" | "past">("all");
  const [assignmentFilter, setAssignmentFilter] = useState<"all" | "assigned" | "unassigned">("all");
  const [statusFilter, setStatusFilter] = useState<"all" | Visit["status"]>("all");
  const today = iso(new Date());
  const visits = workspace.visits.filter((visit) => {
    if (weekStart && (visit.date < weekStart || visit.date > weekEnd!)) return false;
    if (dateFilter === "today" && visit.date !== today) return false;
    if (dateFilter === "upcoming" && visit.date < today) return false;
    if (dateFilter === "past" && visit.date >= today) return false;
    if (assignmentFilter === "assigned" && !visit.caregiver_id) return false;
    if (assignmentFilter === "unassigned" && visit.caregiver_id) return false;
    return statusFilter === "all" || visit.status === statusFilter;
  }).sort((a, b) => `${b.date}T${b.start_time}`.localeCompare(`${a.date}T${a.start_time}`)).slice(0, 50);
  const hasFilters = dateFilter !== "all" || assignmentFilter !== "all" || statusFilter !== "all";
  const reset = () => { setDateFilter("all"); setAssignmentFilter("all"); setStatusFilter("all"); };
  return <LivingCard className="overflow-hidden p-0"><div className="border-b border-white/[.08] p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.18em] text-kelo-200">Latest first</p><h2 className="mt-2 text-xl font-semibold text-white">Appointment updates</h2><p className="mt-2 text-sm text-white/48">Newer visits appear first, so coverage changes and completed care are easy to spot.</p></div><span className="rounded-full border border-white/10 bg-white/[.04] px-3 py-1.5 text-xs font-semibold text-white/60">{visits.length} shown</span></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><div><label htmlFor="appointment-date" className="sr-only">Filter by date</label><select id="appointment-date" value={dateFilter} onChange={(event) => setDateFilter(event.target.value as typeof dateFilter)} className={selectField}><option value="all">Any date</option><option value="today">Today</option><option value="upcoming">Today and upcoming</option><option value="past">Past visits</option></select></div><div><label htmlFor="appointment-assignment" className="sr-only">Filter by assignment</label><select id="appointment-assignment" value={assignmentFilter} onChange={(event) => setAssignmentFilter(event.target.value as typeof assignmentFilter)} className={selectField}><option value="all">All coverage</option><option value="assigned">Assigned</option><option value="unassigned">Unassigned</option></select></div><div className="flex gap-2"><label htmlFor="appointment-status" className="sr-only">Filter by status</label><select id="appointment-status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)} className={selectField}><option value="all">All statuses</option><option value="scheduled">Scheduled</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="missed">Missed</option></select>{hasFilters && <button type="button" onClick={reset} className="shrink-0 rounded-2xl border border-white/12 px-3 text-xs font-semibold text-white/60 transition hover:border-kelo-300/40 hover:text-white">Reset</button>}</div></div></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b border-white/10 bg-white/[.025] text-xs uppercase tracking-[.14em] text-white/35"><tr><th className="px-6 py-3.5">Date</th><th className="px-6 py-3.5">Client</th><th className="px-6 py-3.5">Caregiver</th><th className="px-6 py-3.5">Status</th><th className="px-6 py-3.5 text-right">Time</th></tr></thead><tbody>{visits.length ? visits.map((visit) => <tr key={visit.id} className="border-b border-white/[.065] transition-colors hover:bg-white/[.035]"><td className="px-6 py-4 text-white/55">{new Date(`${visit.date}T12:00:00`).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</td><td className="px-6 py-4 font-medium text-white/82">{client(visit.client_id, workspace)}</td><td className="px-6 py-4"><span className={cn("inline-flex rounded-full px-2.5 py-1 text-xs font-medium", visit.caregiver_id ? "bg-kelo-500/12 text-kelo-100" : "bg-amber-400/10 text-amber-100")}>{visit.caregiver_id ? caregiver(visit.caregiver_id, workspace) : "Unassigned"}</span></td><td className="px-6 py-4"><StatusBadge status={visit.status} /></td><td className="px-6 py-4 text-right font-medium text-white/58">{visit.start_time} - {visit.end_time}</td></tr>) : <tr><td colSpan={5} className="px-6 py-10 text-center text-sm text-white/45">No appointments match these filters.</td></tr>}</tbody></table></div></LivingCard>;
}
function StatusBadge({ status }: { status: Visit["status"] }) { const styles: Record<Visit["status"], string> = { scheduled: "bg-sky-400/10 text-sky-100", in_progress: "bg-violet-400/10 text-violet-100", completed: "bg-emerald-400/10 text-emerald-100", missed: "bg-rose-400/10 text-rose-100" }; return <span className={cn("inline-flex rounded-full px-2.5 py-1 text-xs font-semibold capitalize", styles[status])}>{status.replace("_", " ")}</span>; }
function client(id: string, w: Workspace) { return w.clients.find((c) => c.id === id)?.name || "Client"; }
function caregiver(id: string | null, w: Workspace) { const c = w.caregivers.find((x) => x.id === id); return c ? c.name || c.email : "Unassigned"; }
function assigned(id: string, w: Workspace) { return w.assignments.filter((a) => a.client_id === id).map((a) => caregiver(a.caregiver_id, w)); }
function dayName(value: number) { return DAYS[value === 0 ? 6 : value - 1]; }
function mondayOf(d: Date) { const r = new Date(d); r.setDate(r.getDate() - ((r.getDay() + 6) % 7)); return r; }
function addDays(d: Date, n: number) { const r = new Date(d); r.setDate(r.getDate() + n); return r; }
function iso(d: Date) { return d.toISOString().slice(0, 10); }
function visitHours(visit: Visit) { const [startHour, startMinute] = visit.start_time.split(":").map(Number); const [endHour, endMinute] = visit.end_time.split(":").map(Number); return Math.max(0, (endHour * 60 + endMinute - startHour * 60 - startMinute) / 60); }
function formatHours(hours: number) { return `${Number.isInteger(hours) ? hours : hours.toFixed(1)} hour${hours === 1 ? "" : "s"}`; }
function weeklyPdf(report: { agencyName: string; clientName: string; dateRange: string; summaryLine: string; exception: string; visits: string; medications: string; meals: string; activity: string; comparison: string; nextWeek: string; notes: { text: string; byline: string }[] }) {
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const width = 210;
  const margin = 18;
  const contentWidth = width - margin * 2;
  const printableDateRange = report.dateRange.replace(/[–—]/g, "-");
  const printableSummary = report.summaryLine.replace(/ · /g, " | ");
  let y = 20;
  const nextPage = () => { doc.addPage(); y = 20; };
  const ensureRoom = (height: number) => { if (y + height > 278) nextPage(); };
  const writeWrapped = (text: string, size = 10.5, color: [number, number, number] = [43, 52, 73], lineHeight = 5.5) => {
    doc.setFont("helvetica", "normal"); doc.setFontSize(size); doc.setTextColor(...color);
    const lines = doc.splitTextToSize(text, contentWidth);
    ensureRoom(lines.length * lineHeight + 2);
    doc.text(lines, margin, y, { lineHeightFactor: lineHeight / size });
    y += lines.length * lineHeight;
  };
  const fact = (label: string, value: string) => {
    ensureRoom(18); doc.setFillColor(245, 248, 255); doc.roundedRect(margin, y, contentWidth, 16, 3, 3, "F");
    doc.setFont("helvetica", "bold"); doc.setFontSize(8); doc.setTextColor(68, 89, 159); doc.text(label.toUpperCase(), margin + 5, y + 5.5);
    doc.setFont("helvetica", "normal"); doc.setFontSize(10); doc.setTextColor(31, 41, 55); doc.text(doc.splitTextToSize(value, contentWidth - 10), margin + 5, y + 11, { lineHeightFactor: 1.2 }); y += 19;
  };
  doc.setProperties({ title: `Kelo weekly report - ${report.clientName}`, subject: `Week of ${printableDateRange}`, author: "Kelo Care" });
  doc.setFillColor(20, 54, 190); doc.rect(0, 0, width, 54, "F");
  doc.setFont("helvetica", "bold"); doc.setFontSize(23); doc.setTextColor(255, 255, 255); doc.text("kelo", margin, 21);
  doc.setFontSize(8.5); doc.setTextColor(205, 220, 255); doc.text("WEEKLY CARE REPORT", margin, 31);
  doc.setFontSize(15); doc.setTextColor(255, 255, 255); doc.text(report.clientName, margin, 41);
  doc.setFont("helvetica", "normal"); doc.setFontSize(9); doc.setTextColor(220, 230, 255); doc.text(`Week of ${printableDateRange}`, margin, 48);
  y = 66;
  doc.setFont("helvetica", "bold"); doc.setFontSize(11); doc.setTextColor(20, 35, 90); doc.text(printableSummary, margin, y); y += 10;
  const exceptionLines = doc.splitTextToSize(report.exception, contentWidth - 10);
  const exceptionHeight = Math.max(19, exceptionLines.length * 4.4 + 10);
  doc.setFillColor(232, 239, 255); doc.roundedRect(margin, y, contentWidth, exceptionHeight, 3, 3, "F");
  doc.setFont("helvetica", "bold"); doc.setFontSize(9); doc.setTextColor(20, 54, 190); doc.text("ONE THING TO KNOW", margin + 5, y + 6);
  doc.setFont("helvetica", "normal"); doc.setFontSize(9.5); doc.setTextColor(35, 53, 112); doc.text(exceptionLines, margin + 5, y + 12, { lineHeightFactor: 1.2 }); y += exceptionHeight + 9;
  fact("Visits", report.visits); fact("Medications", report.medications); fact("Meals", report.meals); fact("Activity", report.activity);
  ensureRoom(36); doc.setDrawColor(218, 225, 241); doc.line(margin, y, width - margin, y); y += 8;
  doc.setFont("helvetica", "bold"); doc.setFontSize(10); doc.setTextColor(20, 35, 90); doc.text("Compared with last week", margin, y); y += 6; writeWrapped(report.comparison, 10.5); y += 5;
  doc.setFont("helvetica", "bold"); doc.setFontSize(10); doc.setTextColor(20, 35, 90); doc.text("Next week", margin, y); y += 6; writeWrapped(report.nextWeek, 10.5); y += 8;
  ensureRoom(20); doc.setDrawColor(218, 225, 241); doc.line(margin, y, width - margin, y); y += 9;
  doc.setFont("helvetica", "bold"); doc.setFontSize(12); doc.setTextColor(20, 35, 90); doc.text("From the care team", margin, y); y += 8;
  if (report.notes.length) {
    report.notes.forEach((note) => { const noteLines = doc.splitTextToSize(`"${note.text}"`, contentWidth - 10); const noteHeight = Math.max(20, noteLines.length * 4.4 + 13); ensureRoom(noteHeight + 4); doc.setFillColor(250, 251, 255); doc.roundedRect(margin, y, contentWidth, noteHeight, 3, 3, "F"); doc.setFont("helvetica", "italic"); doc.setFontSize(9.5); doc.setTextColor(48, 57, 78); doc.text(noteLines, margin + 5, y + 6, { lineHeightFactor: 1.2 }); doc.setFont("helvetica", "bold"); doc.setFontSize(8.5); doc.setTextColor(68, 89, 159); doc.text(note.byline, margin + 5, y + noteHeight - 4); y += noteHeight + 4; });
  } else writeWrapped("No caregiver notes were recorded for this client during this week.", 10.5);
  const pages = doc.getNumberOfPages();
  for (let page = 1; page <= pages; page += 1) { doc.setPage(page); doc.setDrawColor(218, 225, 241); doc.line(margin, 286, width - margin, 286); doc.setFont("helvetica", "normal"); doc.setFontSize(7.5); doc.setTextColor(103, 116, 145); doc.text(`${report.agencyName} - Kelo Care`, margin, 291); doc.text(`Page ${page} of ${pages}`, width - margin, 291, { align: "right" }); }
  doc.save(`kelo-weekly-report-${safeFilename(report.clientName)}-${printableDateRange.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.pdf`);
}
function safeFilename(value: string) { return value.trim().replace(/[^a-z0-9]+/gi, "-").replace(/(^-|-$)/g, "").toLowerCase() || "client"; }
function pdf(v: Visit, w: Workspace) { const doc = new jsPDF(); doc.setFontSize(20); doc.text("Kelo Care", 20, 24); doc.setFontSize(14); doc.text("Completed caregiving session", 20, 36); doc.setFontSize(11); doc.text([`Agency: ${w.agencyName}`, `Client: ${client(v.client_id, w)}`, `Caregiver: ${caregiver(v.caregiver_id, w)}`, `Date: ${v.date}`, `Time: ${v.start_time}–${v.end_time}`, "Status: Completed", "", "This report confirms the scheduled session was marked complete in Kelo."], 20, 54, { lineHeightFactor: 1.7 }); doc.save(`kelo-session-${v.date}.pdf`); }
